package reencrypt;

import burp.api.montoya.BurpExtension;
import burp.api.montoya.MontoyaApi;
import burp.api.montoya.ui.editor.extension.EditorCreationContext;
import burp.api.montoya.ui.editor.extension.EditorMode;
import burp.api.montoya.ui.editor.extension.ExtensionProvidedHttpRequestEditor;
import burp.api.montoya.ui.editor.extension.ExtensionProvidedHttpResponseEditor;
import burp.api.montoya.ui.editor.extension.HttpRequestEditorProvider;
import burp.api.montoya.ui.editor.extension.HttpResponseEditorProvider;
import reencrypt.ui.RequestTab;
import reencrypt.ui.ResponseTab;
import reencrypt.ui.SettingsTab;

public class App implements BurpExtension {
    public static final String name = "Re:Encrypt/v1";

    public void initialize(MontoyaApi api) {
        api.extension().setName(name);

        var config = new Config(api.persistence());
        for (String error : config.getLoadErrors()) {
            api.logging().logToError(error);
        }
        SettingsTab settingsTab = new SettingsTab(api, config);
        api.userInterface().registerSuiteTab(name, settingsTab.uiComponent());

        var reEncrypt = new ReEncrypt(config);
        api.userInterface().registerHttpRequestEditorProvider(new HttpRequestEditorProvider() {
            public ExtensionProvidedHttpRequestEditor provideHttpRequestEditor(EditorCreationContext creationContext) {
                return new RequestTab(api, reEncrypt, creationContext.editorMode() == EditorMode.READ_ONLY,
                        creationContext.toolSource().toolType());
            }
        });
        api.userInterface().registerHttpResponseEditorProvider(new HttpResponseEditorProvider() {
            public ExtensionProvidedHttpResponseEditor provideHttpResponseEditor(
                    EditorCreationContext creationContext) {
                return new ResponseTab(api, reEncrypt, creationContext.editorMode() == EditorMode.READ_ONLY,
                        creationContext.toolSource().toolType());
            }
        });
        api.proxy().registerRequestHandler(new ProxyHandler(api, reEncrypt));
        api.proxy().registerResponseHandler(new ProxyHandler(api, reEncrypt));
        api.http().registerHttpHandler(new IntruderHandler(api, reEncrypt));
        api.intruder().registerPayloadProcessor(new IntruderPayloadProcessor(api, reEncrypt));
        api.userInterface().registerContextMenuItemsProvider(new AnalyzeContextMenuProvider(settingsTab));

        AutoLoader autoLoader = new AutoLoader(config, api.logging()::logToOutput);
        settingsTab.setAutoLoader(autoLoader);
        if (config.isAutoLoadEnabled()) {
            autoLoader.start(config.getAutoLoadPath(), config.getAutoLoadIntervalSeconds());
        }
    }

}
